      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-plugin-feishu\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Feishu (Lark) tools for DeepSeek Harness: send messages, read chat history, create/read/append Feishu documents, and grant document access.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./client/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"client\",\n    \"assets\",\n    \"cordis.patch.yml\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"feishu\",\n    \"lark\",\n    \"docs\",\n    \"chat\",\n    \"bot\"\n  ],\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/2286893544/feishu-dsh-plugin.git\"\n  },\n  \"homepage\": \"https://github.com/2286893544/feishu-dsh-plugin#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/2286893544/feishu-dsh-plugin/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ]\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.0-rc.7 || ^0.1.1-rc.2 || ^0.1.2-alpha.2\",\n    \"@deepseek-ai/dsh-skill\": \"^0.1.2-alpha.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.2-alpha.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"engines\": {\n    \"node\": \">=18.0.0\"\n  }\n}\n"
    },
