      "path": "lib/index.js",
      "content": "// dsh-plugin-feishu — Feishu tools + bundled skill provider for DeepSeek Harness.\n// Registers model-facing `feishu_*` tools (inject: tools) and a bundled\n// `feishu` skill (inject: skills), backed by a pure-Node Feishu REST client.\n\nimport { readFile } from \"node:fs/promises\";\nimport { fileURLToPath } from \"node:url\";\nimport path from \"node:path\";\nimport z from \"@deepseek-ai/schemastery\";\nimport { BUNDLED_SKILL_RANK } from \"@deepseek-ai/dsh-skill\";\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\nimport { FeishuClient } from \"./client.js\";\nimport { renderBarChart } from \"./png.js\";\nimport { installFeishuSettings } from \"./settings.js\";\nimport { fingerprint, mountFeishuRoutes } from \"./routes.js\";\n\nexport const name = \"feishu-bridge\";\nexport const inject = [\"tools\", \"skills\"];\n\n/**\n * Plugin configuration, rendered by the harness settings UI\n * (Settings → Plugins → Plugin configuration). The secret field is marked with\n * `role(\"secret\")` so the settings service redacts it from remote reads and the\n * UI renders a password input.\n */\nexport const Config = z.object({\n  appId: z.string().description(\"Feishu app ID of your self-built app (cli_...).\"),\n  appSecret: z.string().role(\"secret\").description(\"Feishu app secret. Stored in the local profile and masked in the UI.\"),\n  tenantDomain: z.string().description(\"Optional tenant domain such as acme.feishu.cn; auto-detected from the tenant API when omitted.\"),\n  defaultChatId: z.string().description(\"Optional default chat_id (oc_...) used by chat tools when the call omits chat_id.\"),\n  grantOpenId: z.string().description(\"Optional open_id (ou_...) granted full_access on every document/bitable this plugin creates, so the human operating the bot stays in full control of what the bot makes.\"),\n  wikiSpaceId: z.string().description(\"Optional knowledge-base space id (digits). When set, feishu_create_document creates documents inside this knowledge base and returns a /wiki/ link.\"),\n  wikiParentNodeToken: z.string().description(\"Optional knowledge-base node token used as the default parent for new wiki documents; empty means the knowledge-base root.\"),\n});\n\n// ---------- bundled skill ----------\nconst SKILL_NAME = \"feishu\";\nconst ASSET_DIR_URL = new URL(\"../assets/\", import.meta.url);\nconst SKILL_BODY_URL = new URL(\"../assets/feishu.md\", import.meta.url);\nconst RESOURCE_BASE = { kind: \"directory\", path: fileURLToPath(ASSET_DIR_URL) };\n\nconst skillCandidate = {\n  name: SKILL_NAME,\n  description:\n    \"Operate Feishu (Lark) through the configured self-built app: send text or rich-text messages, read chat history and members, recall messages, create/read/edit documents (including tables, images and generated charts), manage bitable records, and read or write spreadsheet ranges. Use whenever the user asks to work with their Feishu docs, chat records, multi-dimensional tables or spreadsheets.\",\n  invocation: { modelInvocable: true, userInvocable: true },\n  provider: \"feishu-bridge\",\n  source: \"bundled\",\n  resourceBase: RESOURCE_BASE,\n  rank: BUNDLED_SKILL_RANK,\n  locator: SKILL_BODY_URL,\n};\n\nconst skillProvider = {\n  name: \"feishu-bridge\",\n  list: () => Promise.resolve([skillCandidate]),\n  async get(_candidate) {\n    return {\n      name: skillCandidate.name,\n      description: skillCandidate.description,\n      invocation: skillCandidate.invocation,\n      provider: skillCandidate.provider,\n      source: skillCandidate.source,\n      resourceBase: RESOURCE_BASE,\n      content: await readFile(SKILL_BODY_URL, \"utf8\"),\n    };\n  },\n};\n\n// ---------- shared tool plumbing ----------\n// Every tool returns { result: <text> }; the renderer forwards it to the model.\nconst textOutput = {\n  schema: {\n    type: \"object\",\n    additionalProperties: false,\n    properties: { result: { type: \"string\", required: true } },\n  },\n  render: (_args, value) => [{ type: \"text\", text: String(value?.result ?? \"\") }],\n};\n\nfunction fmtTime(ms) {\n  const n = Number(ms);\n  if (!Number.isFinite(n) || n <= 0) return String(ms ?? \"\");\n  return new Date(n).toISOString().replace(\"T\", \" \").replace(\".000Z\", \"Z\");\n}\n\nfunction json(value) {\n  return JSON.stringify(value, null, 1);\n}\n\nfunction tool(spec, run) {\n  return defineTool({\n    name: spec.name,\n    description: spec.description,\n    parameters: spec.parameters ?? {},\n    output: textOutput,\n    async execute(args) {\n      return { result: await run(args) };\n    },\n  });\n}\n\nasync function loadImageBytes({ image_path, image_url, image_base64 }) {\n  if (image_path) {\n    const buffer = await readFile(image_path);\n    return { buffer, filename: path.basename(image_path) };\n  }\n  if (image_url) {\n    const res = await fetch(image_url, { signal: AbortSignal.timeout(60_000) });\n    if (!res.ok) throw new Error(`failed to download image: HTTP ${res.status}`);\n    const buffer = Buffer.from(await res.arrayBuffer());\n    const name = path.basename(new URL(image_url).pathname) || \"image.png\";\n    return { buffer, filename: name };\n  }\n  if (image_base64) {\n    const cleaned = image_base64.replace(/^data:[^;]+;base64,/, \"\");\n    return { buffer: Buffer.from(cleaned, \"base64\"), filename: \"image.png\" };\n  }\n  throw new Error(\"provide one of image_path, image_url or image_base64\");\n}\n\n// ---------- tools ----------\n/**\n * Give the configured human full control over anything the bot creates.\n * Feishu keeps app-created documents in the app's own space and records the app\n * identity as the owner, so without this the person operating the bot is merely\n * \"someone holding a link\". A failed grant must never break doc creation.\n */\nasync function autoGrantOwner(client, config, token, type) {\n  const openId = (config?.grantOpenId ?? \"\").trim();\n  if (!openId) return \"\";\n  try {\n    await client.grantAccess(token, type, openId, \"full_access\");\n    return `  granted full_access to ${openId}`;\n  } catch (error) {\n    return `  auto-grant failed: ${error?.message ?? String(error)}`;\n  }\n}\n\nfunction toolsOf(client, config = {}) {\n  const chatId = (value) => {\n    const id = value || config.defaultChatId;\n    if (!id) {\n      throw new Error(\"chat_id is required (or set defaultChatId in the plugin configuration)\");\n    }\n    return id;\n  };\n  return [\n    // ----- chat / messages -----\n    tool({\n      name: \"feishu_list_chats\",\n      description: \"List the Feishu chats (groups / p2p sessions) the configured bot is in, with chat_id and name.\",\n    }, async () => {\n      const chats = await client.listChats();\n      return chats.length === 0\n        ? \"(no chats: the bot is not in any group, or the app lacks chat read scope)\"\n        : chats.map((c) => `chat_id=${c.chat_id}  name=${c.name}`).join(\"\\n\");\n    }),\n\n    tool({\n      name: \"feishu_list_chat_members\",\n      description: \"List members of a Feishu chat with their open_id and display name (use the open_id to grant document access).\",\n      parameters: {\n        chat_id: { type: \"string\", description: \"The Feishu chat_id (oc_...); defaults to the configured defaultChatId.\" },\n        limit: { type: \"number\", description: \"Maximum members to return (default 100).\" },\n      },\n    }, async (args) => {\n      const members = await client.listChatMembers(chatId(args.chat_id), args.limit ?? 100);\n      return members.length === 0\n        ? \"(no members returned)\"\n        : members.map((m) => `open_id=${m.member_id}  name=${m.name ?? \"(unknown)\"}`).join(\"\\n\");\n    }),\n\n    tool({\n      name: \"feishu_send_text\",\n      description: \"Send a plain-text message to a Feishu chat (group or p2p) as the configured bot.\",\n      parameters: {\n        chat_id: { type: \"string\", description: \"The Feishu chat_id (oc_...) to send to; defaults to the configured defaultChatId.\" },\n        text: { type: \"string\", required: true, description: \"The message text to send.\" },\n      },\n    }, async (args) => {\n      const sent = await client.sendText(chatId(args.chat_id), args.text);\n      return `sent message_id=${sent.message_id} create_time=${fmtTime(sent.create_time)}`;\n    }),\n\n    tool({\n      name: \"feishu_send_post_message\",\n      description: \"Send a rich-text (post) message with an optional title and multi-line body to a Feishu chat. Full-width colons and emoji are fine; the body is sent as plain text paragraphs.\",\n      parameters: {\n        chat_id: { type: \"string\", description: \"The Feishu chat_id (oc_...); defaults to the configured defaultChatId.\" },\n        title: { type: \"string\", description: \"Optional message title.\" },\n        lines: {\n          type: \"array\",\n          items: { type: \"string\" },\n          description: \"Body lines, each rendered as its own paragraph.\",\n        },\n      },\n    }, async (args) => {\n      const sent = await client.sendPost(chatId(args.chat_id), args.title, args.lines || []);\n      return `sent post message_id=${sent.message_id} create_time=${fmtTime(sent.create_time)}`;\n    }),\n\n    tool({\n      name: \"feishu_read_chat_history\",\n      description: \"Read recent messages of a Feishu chat the bot is in, in chronological order. Requires the app scope for reading group history.\",\n      parameters: {\n        chat_id: { type: \"string\", description: \"The Feishu chat_id (oc_...); defaults to the configured defaultChatId.\" },\n        limit: { type: \"number\", description: \"How many of the most recent messages to return (default 30, max 100).\" },\n      },\n    }, async (args) => {\n      const messages = await client.readChatHistory(chatId(args.chat_id), args.limit);\n      return messages.length === 0\n        ? \"(no messages)\"\n        : messages\n            .map((m) => `[${fmtTime(m.create_time)}] ${m.sender_type || \"unknown\"} <${m.msg_type}>: ${m.text}`)\n            .join(\"\\n\");\n    }),\n\n    tool({\n      name: \"feishu_recall_message\",\n      description: \"Recall (withdraw) a message the bot has sent. Only messages sent by this bot can be recalled.\",\n      parameters: {\n        message_id: { type: \"string\", required: true, description: \"The message_id (om_...) returned when the bot sent the message.\" },\n      },\n    }, async (args) => {\n      const done = await client.recallMessage(args.message_id);\n      return `recalled message_id=${done.message_id}`;\n    }),\n\n    // ----- documents -----\n    tool({\n      name: \"feishu_create_document\",\n      description: \"Create a new Feishu document (docx) with a title and optional plain-text paragraphs. When a knowledge-base space is configured, the document is created INSIDE that knowledge base and the returned url is a /wiki/ link; pass standalone=true to create a plain document in the app cloud space instead.\",\n      parameters: {\n        title: { type: \"string\", required: true, description: \"Document title.\" },\n        paragraphs: {\n          type: \"array\",\n          items: { type: \"string\" },\n          description: \"Optional plain-text paragraphs to write into the document.\",\n        },\n        parent_node_token: { type: \"string\", description: \"Optional knowledge-base node token to create the document under; defaults to the configured wikiParentNodeToken.\" },\n        standalone: { type: \"boolean\", description: \"Create a plain document in the app own cloud space instead of the knowledge base.\" },\n      },\n    }, async (args) => {\n      const spaceId = (config?.wikiSpaceId ?? \"\").trim();\n      if (spaceId && !args.standalone) {\n        const parent = (args.parent_node_token ?? config?.wikiParentNodeToken ?? \"\").trim();\n        const doc = await client.createWikiDocument(spaceId, args.title, args.paragraphs || [], parent);\n        const grant = await autoGrantOwner(client, config, doc.document_id, \"docx\");\n        return `created wiki document_id=${doc.document_id}  node_token=${doc.node_token}${doc.url ? `  url=${doc.url}` : \"\"}${grant}`;\n      }\n      const doc = await client.createDocument(args.title, args.paragraphs || []);\n      const grant = await autoGrantOwner(client, config, doc.document_id, \"docx\");\n      return `created document_id=${doc.document_id}${doc.url ? `  url=${doc.url}` : \"\"}${grant}`;\n    }),\n\n    tool({\n      name: \"feishu_resolve_wiki_node\",\n      description: \"Resolve a knowledge-base (wiki) node token or /wiki/ link to the underlying document_id, so the read and edit tools can work on that page.\",\n      parameters: {\n        node_token: { type: \"string\", required: true, description: \"Wiki node token: the last path segment of a /wiki/ link.\" },\n      },\n    }, async (args) => {\n      const token = String(args.node_token).trim().split(\"/wiki/\").pop().split(\"?\")[0].split(\"#\")[0];\n      const node = await client.getWikiNode(token);\n      if (!node) return `wiki node ${token} not found`;\n      return `node_token=${node.node_token}  title=${node.title ?? \"\"}  obj_type=${node.obj_type}  document_id=${node.obj_token}  space_id=${node.space_id}  parent_node_token=${node.parent_node_token || \"(root)\"}`;\n    }),\n\n    tool({\n      name: \"feishu_read_document\",\n      description: \"Read the plain-text content of an existing Feishu cloud document (docx) the app can access.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n      },\n    }, async (args) => {\n      const doc = await client.readDocument(args.document_id);\n      return doc.content;\n    }),\n\n    tool({\n      name: \"feishu_read_document_blocks\",\n      description: \"Read a document's block structure (block_id, type, text, image token, table size) instead of plain text — needed to locate images, tables, or a specific block before editing it.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n      },\n    }, async (args) => {\n      const blocks = await client.readDocumentBlocks(args.document_id);\n      const counts = {};\n      for (const b of blocks) counts[b.block_type] = (counts[b.block_type] || 0) + 1;\n      const lines = blocks.map((b) => {\n        const extra = b.table_size ? ` table=${b.table_size.rows}x${b.table_size.columns}` : b.image_token ? \" image\" : \"\";\n        return `${b.block_id} type=${b.block_type}${extra}${b.text ? `: ${b.text.slice(0, 80)}` : \"\"}`;\n      });\n      return `total blocks: ${blocks.length}  by type: ${json(counts)}\\n${lines.join(\"\\n\")}`;\n    }),\n\n    tool({\n      name: \"feishu_append_document_blocks\",\n      description: \"Append text blocks to an existing Feishu cloud document. Supported kinds: text, heading1, heading2, bullet, quote.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n        blocks: {\n          type: \"array\",\n          items: {\n            type: \"object\",\n            additionalProperties: false,\n            properties: {\n              kind: { type: \"string\", enum: [\"text\", \"heading1\", \"heading2\", \"bullet\", \"quote\"], description: \"Block kind; defaults to text.\" },\n              text: { type: \"string\" },\n            },\n          },\n          description: \"Blocks to append, in order.\",\n        },\n      },\n    }, async (args) => {\n      const added = await client.appendBlocks(args.document_id, args.blocks || []);\n      return `appended ${added.added} block(s) to document_id=${args.document_id}`;\n    }),\n\n    tool({\n      name: \"feishu_update_document_block\",\n      description: \"Replace the text of one existing document block (text or heading1 block) by block_id.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n        block_id: { type: \"string\", required: true, description: \"Target block_id (see feishu_read_document_blocks).\" },\n        text: { type: \"string\", required: true, description: \"New text content.\" },\n        kind: { type: \"string\", enum: [\"text\", \"heading1\"], description: \"Block kind; defaults to text.\" },\n      },\n    }, async (args) => {\n      await client.updateBlockText(args.document_id, args.block_id, args.text, args.kind || \"text\");\n      return `updated block_id=${args.block_id}`;\n    }),\n\n    tool({\n      name: \"feishu_delete_document_block\",\n      description: \"Delete one document block by block_id.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n        block_id: { type: \"string\", required: true, description: \"Target block_id.\" },\n      },\n    }, async (args) => {\n      await client.deleteBlock(args.document_id, args.block_id);\n      return `deleted block_id=${args.block_id}`;\n    }),\n\n    tool({\n      name: \"feishu_insert_table_into_document\",\n      description: \"Insert an empty table with the given number of rows and columns into a document, returning its table block_id.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n        rows: { type: \"number\", required: true, description: \"Row count.\" },\n        columns: { type: \"number\", required: true, description: \"Column count.\" },\n      },\n    }, async (args) => {\n      const table = await client.insertTable(args.document_id, args.rows, args.columns);\n      return `inserted table ${table.rows}x${table.columns} table_block_id=${table.table_block_id}`;\n    }),\n\n    tool({\n      name: \"feishu_insert_image_into_document\",\n      description: \"Insert an image into a document. Supply the image as a local path (image_path), a public https URL (image_url), or base64 (image_base64).\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n        image_path: { type: \"string\", description: \"Local file path of the image.\" },\n        image_url: { type: \"string\", description: \"https URL of the image.\" },\n        image_base64: { type: \"string\", description: \"Base64 image data (data URI accepted).\" },\n      },\n    }, async (args) => {\n      const { buffer, filename } = await loadImageBytes(args);\n      const inserted = await client.insertImage(args.document_id, buffer, filename);\n      return `inserted image block_id=${inserted.block_id} bytes=${inserted.bytes}`;\n    }),\n\n    tool({\n      name: \"feishu_insert_chart_into_document\",\n      description: \"Render a bar chart locally (no dependencies) and insert it into a document. Title and category labels are drawn with an uppercase ASCII 5x7 font; non-ASCII characters are dropped, so keep labels ASCII or omit them.\",\n      parameters: {\n        document_id: { type: \"string\", required: true, description: \"The docx document_id.\" },\n        title: { type: \"string\", description: \"Chart title (ASCII).\" },\n        categories: { type: \"array\", items: { type: \"string\" }, description: \"Bar labels (ASCII), one per value.\" },\n        values: { type: \"array\", items: { type: \"number\" }, description: \"Bar values, one per category.\" },\n      },\n    }, async (args) => {\n      const values = (args.values || []).map((v) => Number(v) || 0);\n      if (values.length === 0) throw new Error(\"values is required (one number per bar)\");\n      const png = renderBarChart({\n        title: args.title || \"\",\n        categories: args.categories || [],\n        values,\n      });\n      const inserted = await client.insertImage(args.document_id, png, \"chart.png\");\n      return `inserted chart block_id=${inserted.block_id} bars=${values.length} bytes=${inserted.bytes}`;\n    }),\n\n    // ----- bitable -----\n    tool({\n      name: \"feishu_create_bitable\",\n      description: \"Create a new Feishu bitable (multi-dimensional table) and return its app_token, plus a share URL.\",\n      parameters: {\n        name: { type: \"string\", required: true, description: \"Bitable name.\" },\n      },\n    }, async (args) => {\n      const app = await client.createBitable(args.name);\n      const grant = await autoGrantOwner(client, config, app.app_token, \"bitable\");\n      return `created bitable app_token=${app.app_token}${app.url ? `  url=${app.url}` : \"\"}${grant}`;\n    }),\n\n    tool({\n      name: \"feishu_list_bitable_tables\",\n      description: \"List the data tables inside a bitable.\",\n      parameters: { app_token: { type: \"string\", required: true, description: \"The bitable app_token.\" } },\n    }, async (args) => {\n      const tables = await client.listBitableTables(args.app_token);\n      return tables.length === 0\n        ? \"(no tables)\"\n        : tables.map((t) => `table_id=${t.table_id}  name=${t.name}`).join(\"\\n\");\n    }),\n\n    tool({\n      name: \"feishu_list_bitable_fields\",\n      description: \"List the fields (columns) of a bitable data table, with field_id, name and numeric type.\",\n      parameters: {\n        app_token: { type: \"string\", required: true, description: \"The bitable app_token.\" },\n        table_id: { type: \"string\", required: true, description: \"The table_id (tbl...).\" },\n      },\n    }, async (args) => {\n      const fields = await client.listBitableFields(args.app_token, args.table_id);\n      return fields.length === 0\n        ? \"(no fields)\"\n        : fields.map((f) => `field_id=${f.field_id}  name=${f.field_name}  type=${f.type}`).join(\"\\n\");\n    }),\n\n    tool({\n      name: \"feishu_write_bitable_record\",\n      description: \"Create one record in a bitable data table. Field keys are field names (call feishu_list_bitable_fields first); values must match each field's type.\",\n      parameters: {\n        app_token: { type: \"string\", required: true, description: \"The bitable app_token.\" },\n        table_id: { type: \"string\", required: true, description: \"The table_id (tbl...).\" },\n        fields: {\n          type: \"object\",\n          additionalProperties: true,\n          description: \"Field name to value map, e.g. {\\\"文本\\\":\\\"hello\\\"}.\",\n        },\n      },\n    }, async (args) => {\n      const rec = await client.createBitableRecord(args.app_token, args.table_id, args.fields || {});\n      return `created record_id=${rec.record_id}\\nfields=${json(rec.fields)}`;\n    }),\n\n    tool({\n      name: \"feishu_read_bitable_records\",\n      description: \"Read records from a bitable data table.\",\n      parameters: {\n        app_token: { type: \"string\", required: true, description: \"The bitable app_token.\" },\n        table_id: { type: \"string\", required: true, description: \"The table_id (tbl...).\" },\n        limit: { type: \"number\", description: \"Maximum records to return (default 20, max 100).\" },\n      },\n    }, async (args) => {\n      const records = await client.listBitableRecords(args.app_token, args.table_id, args.limit ?? 20);\n      return records.length === 0\n        ? \"(no records)\"\n        : records.map((r) => `${r.record_id} ${json(r.fields)}`).join(\"\\n\");\n    }),\n\n    // ----- sheets -----\n    tool({\n      name: \"feishu_read_sheet_range\",\n      description: \"Read a spreadsheet range (classic sheets v2 API), e.g. range \\\"sheetId!A1:C5\\\".\",\n      parameters: {\n        spreadsheet_token: { type: \"string\", required: true, description: \"The spreadsheet token from the sheet URL.\" },\n        range: { type: \"string\", required: true, description: \"Range such as \\\"<sheetId>!A1:C5\\\".\" },\n      },\n    }, async (args) => {\n      const data = await client.readSheetRange(args.spreadsheet_token, args.range);\n      return `range=${data.range}\\n${json(data.values)}`;\n    }),\n\n    tool({\n      name: \"feishu_write_sheet_range\",\n      description: \"Write values into a spreadsheet range (classic sheets v2 API). values is a 2D array of rows.\",\n      parameters: {\n        spreadsheet_token: { type: \"string\", required: true, description: \"The spreadsheet token from the sheet URL.\" },\n        range: { type: \"string\", required: true, description: \"Range such as \\\"<sheetId>!A1:B2\\\".\" },\n        values: {\n          type: \"array\",\n          items: {\n            type: \"array\",\n            items: {\n              oneOf: [\n                { type: \"string\" },\n                { type: \"number\" },\n                { type: \"boolean\" },\n              ],\n            },\n          },\n          description: \"2D array of cell values, e.g. [[\\\"a\\\",1],[\\\"b\\\",2]].\",\n        },\n      },\n    }, async (args) => {\n      const done = await client.writeSheetRange(args.spreadsheet_token, args.range, args.values || []);\n      return `written cells=${done.updated} range=${done.range}`;\n    }),\n\n    // ----- drive permission -----\n    tool({\n      name: \"feishu_grant_document_access\",\n      description: \"Grant a Feishu user (open_id) full access to a document or bitable the app owns, so it appears in that user's drive.\",\n      parameters: {\n        token: { type: \"string\", required: true, description: \"The drive token: a docx document_id or a bitable app_token.\" },\n        type: { type: \"string\", required: true, enum: [\"docx\", \"bitable\"], description: \"The asset type.\" },\n        open_id: { type: \"string\", required: true, description: \"The recipient user's open_id.\" },\n      },\n    }, async (args) => {\n      const granted = await client.grantAccess(args.token, args.type, args.open_id);\n      return `granted ${granted.perm} on ${granted.type} ${granted.token} to ${granted.open_id}`;\n    }),\n\n    tool({\n      name: \"feishu_set_document_link_sharing\",\n      description: \"Set link sharing on a document or bitable the app owns, so anyone in the tenant (or anyone with the link) can open it. Use this right after creating a document/bitable and posting its link into a chat, otherwise the link opens an access-denied page for everyone but the app.\",\n      parameters: {\n        token: { type: \"string\", required: true, description: \"The drive token: a docx document_id or a bitable app_token.\" },\n        type: { type: \"string\", required: true, enum: [\"docx\", \"bitable\"], description: \"The asset type.\" },\n        link_share_entity: {\n          type: \"string\",\n          enum: [\"tenant_readable\", \"tenant_editable\", \"anyone_readable\", \"anyone_editable\"],\n          description: \"Who may open the link. Defaults to tenant_readable (anyone in your organization can read).\",\n        },\n      },\n    }, async (args) => {\n      const done = await client.setLinkSharing(args.token, args.type, args.link_share_entity || \"tenant_readable\");\n      return `link sharing on ${done.type} ${done.token} set to ${done.link_share_entity}`;\n    }),\n  ];\n}\n\n// ---------- plugin ----------\nfunction resolveConfiguration(config = {}) {\n  const env = process.env;\n  return {\n    appId: config.appId ?? env.FEISHU_APP_ID ?? \"\",\n    appSecret: config.appSecret ?? env.FEISHU_APP_SECRET ?? \"\",\n    tenantDomain: config.tenantDomain ?? env.FEISHU_TENANT_DOMAIN ?? \"\",\n    defaultChatId: config.defaultChatId ?? env.FEISHU_DEFAULT_CHAT_ID ?? \"\",\n    grantOpenId: config.grantOpenId ?? env.FEISHU_GRANT_OPEN_ID ?? \"\",\n    wikiSpaceId: config.wikiSpaceId ?? env.FEISHU_WIKI_SPACE_ID ?? \"\",\n    wikiParentNodeToken: config.wikiParentNodeToken ?? env.FEISHU_WIKI_PARENT_NODE_TOKEN ?? \"\",\n  };\n}\n\n/**\n * Non-secret connection report for the settings page. Runs on the host, because\n * the stored secret never reaches the browser.\n * @param client - live REST client (uses the current credentials).\n * @param resolved - live credentials object.\n * @param config - the composed loader configuration, for source reporting.\n * @returns human-verifiable facts: which app answered, which tenant, masked key.\n */\nasync function testConnection(client, resolved, config = {}) {\n  const tenant = await client.tenantInfo();\n  const bot = await client.botInfo().catch(() => null);\n  return {\n    appId: resolved.appId || null,\n    secretFingerprint: fingerprint(resolved.appSecret),\n    botName: bot?.app_name ?? null,\n    botActivateStatus: bot?.activate_status ?? null,\n    tenantName: tenant?.name ?? null,\n    tenantDomain: tenant?.domain ?? null,\n    sources: {\n      environment: Boolean(process.env.FEISHU_APP_ID || process.env.FEISHU_APP_SECRET),\n      profileConfig: Object.values(config ?? {}).some((value) => typeof value === \"string\" && value.length > 0),\n    },\n  };\n}\n\nfunction apply(ctx, config = {}) {\n  const resolved = resolveConfiguration(config);\n  const client = new FeishuClient(resolved);\n  // The settings card writes into this namespace; each change lands on the live\n  // credentials object and is pushed straight into the REST client, so a saved\n  // edit takes effect without a restart.\n  installFeishuSettings(ctx, resolved, () => client.updateCredentials(resolved));\n  for (const tool of toolsOf(client, resolved)) ctx.tools.register(tool);\n  ctx.skills.registerProvider(() => skillProvider);\n\n  // HTTP route behind the settings page's \"test connection\" button.\n  ctx.inject([\"webServer\"], (host) => {\n    host.effect?.(\n      () => mountFeishuRoutes(host, { testConnection: () => testConnection(client, resolved, config) }),\n      \"feishu-bridge: test-connection route\",\n    );\n  });\n}\n\nexport { apply };\n"
    },
    {
      "path": "lib/client.js",
      "content": "// Feishu (Lark) Open Platform REST client — pure Node (global fetch), no external deps.\n// Security: never logs appSecret or tenant_access_token.\n\nconst BASE_URL = \"https://open.feishu.cn\";\nconst TOKEN_EXPIRY_BUFFER_MS = 60_000;\n\nexport class FeishuError extends Error {\n  constructor(code, msg, raw) {\n    super(`Feishu API error ${code}: ${msg}`);\n    this.code = code;\n    this.msg = msg;\n    this.raw = raw;\n  }\n}\n\nfunction assertString(value, name) {\n  if (typeof value !== \"string\" || value.length === 0) {\n    throw new Error(`${name} is required`);\n  }\n  return value;\n}\n\nexport class FeishuClient {\n  constructor({ appId, appSecret, tenantDomain, timeoutMs = 30_000 } = {}) {\n    // Credentials may be empty at construction time: the plugin loads before the\n    // user configures it (the settings card must exist to be filled in), and every\n    // request validates them.\n    this.appId = typeof appId === \"string\" ? appId : \"\";\n    this.appSecret = typeof appSecret === \"string\" ? appSecret : \"\";\n    this.tenantDomain = tenantDomain || null;\n    this.timeoutMs = timeoutMs;\n    this.token = null;\n    this.tokenExpiresAt = 0;\n  }\n\n  /** Apply changed credentials (a settings-UI edit) without recreating the client. */\n  updateCredentials({ appId, appSecret, tenantDomain } = {}) {\n    const appIdChanged = typeof appId === \"string\" && appId !== this.appId;\n    const secretChanged = typeof appSecret === \"string\" && appSecret !== this.appSecret;\n    if (appIdChanged) this.appId = appId;\n    if (secretChanged) this.appSecret = appSecret;\n    if (typeof tenantDomain === \"string\" && tenantDomain !== this.tenantDomain) {\n      this.tenantDomain = tenantDomain || null;\n      this._domain = undefined;\n    }\n    if (appIdChanged || secretChanged) {\n      this.token = null;\n      this.tokenExpiresAt = 0;\n    }\n  }\n\n  // ---------- transport ----------\n  async _token() {\n    if (this.token && Date.now() < this.tokenExpiresAt) return this.token;\n    if (!this.appId || !this.appSecret) {\n      throw new Error(\n        \"feishu-bridge is not configured: set appId and appSecret in \" +\n        \"Settings → Plugins → Plugin configuration (or provide FEISHU_APP_ID / FEISHU_APP_SECRET).\"\n      );\n    }\n    const data = await this._request(\"POST\", \"/open-apis/auth/v3/tenant_access_token/internal\", {\n      app_id: this.appId,\n      app_secret: this.appSecret,\n    }, { auth: false });\n    if (data.code !== 0) throw new FeishuError(data.code, data.msg || \"token exchange failed\", data);\n    this.token = data.tenant_access_token;\n    this.tokenExpiresAt = Date.now() + (Number(data.expire) || 7200) * 1000 - TOKEN_EXPIRY_BUFFER_MS;\n    return this.token;\n  }\n\n  async _request(method, path, body, { auth = true } = {}) {\n    const headers = { \"Content-Type\": \"application/json; charset=utf-8\" };\n    if (auth) headers.Authorization = `Bearer ${await this._token()}`;\n    const init = { method, headers, signal: AbortSignal.timeout(this.timeoutMs) };\n    if (body !== undefined) init.body = JSON.stringify(body);\n    let res;\n    try {\n      res = await fetch(BASE_URL + path, init);\n    } catch (err) {\n      throw new Error(`network error calling ${path}: ${err.message}`);\n    }\n    const text = await res.text();\n    let parsed = {};\n    if (text) {\n      try {\n        parsed = JSON.parse(text);\n      } catch {\n        throw new Error(`unexpected response from ${path}: ${text.slice(0, 200)}`);\n      }\n    }\n    if (!res.ok && parsed.code === undefined) {\n      throw new Error(`HTTP ${res.status} from ${path}: ${text.slice(0, 200)}`);\n    }\n    return parsed;\n  }\n\n  async _api(method, path, body) {\n    let data = await this._request(method, path, body);\n    if ([99991663, 99991664, 99991668].includes(data.code)) {\n      this.token = null;\n      this.tokenExpiresAt = 0;\n      data = await this._request(method, path, body);\n    }\n    if (data.code !== 0) throw new FeishuError(data.code, data.msg || \"request failed\", data);\n    return data.data !== undefined ? data.data : data;\n  }\n\n  async _upload(path, formData) {\n    const res = await fetch(BASE_URL + path, {\n      method: \"POST\",\n      headers: { Authorization: `Bearer ${await this._token()}` },\n      body: formData,\n      signal: AbortSignal.timeout(120_000),\n    });\n    const text = await res.text();\n    let data = {};\n    try {\n      data = text ? JSON.parse(text) : {};\n    } catch {\n      throw new Error(`unexpected upload response: ${text.slice(0, 200)}`);\n    }\n    if (data.code !== 0) throw new FeishuError(data.code, data.msg || \"upload failed\", data);\n    return data.data ?? data;\n  }\n\n  // ---------- tenant ----------\n  /** Tenant facts (name, domain) — obtaining them also proves the credentials work. */\n  async tenantInfo() {\n    const data = await this._api(\"GET\", \"/open-apis/tenant/v2/tenant/query\");\n    return data?.tenant ?? null;\n  }\n\n  /** The bot's own identity, for a human-readable \"which app is this\" check. */\n  async botInfo() {\n    const data = await this._api(\"GET\", \"/open-apis/bot/v3/info\");\n    return data?.bot ?? data ?? null;\n  }\n\n  /** Resolve the tenant domain (e.g. \"acme.feishu.cn\") once, for building share URLs. */\n  async resolveTenantDomain() {\n    if (this.tenantDomain) return this.tenantDomain;\n    if (this._domain === undefined) {\n      try {\n        const data = await this._api(\"GET\", \"/open-apis/tenant/v2/tenant/query\");\n        this._domain = data?.tenant?.domain || null;\n      } catch {\n        this._domain = null;\n      }\n    }\n    return this._domain;\n  }\n\n  async documentUrl(documentId) {\n    const domain = await this.resolveTenantDomain();\n    return domain ? `https://${domain}/docx/${documentId}` : null;\n  }\n\n  async bitableUrl(appToken) {\n    const domain = await this.resolveTenantDomain();\n    return domain ? `https://${domain}/base/${appToken}` : null;\n  }\n\n  /** Wiki URL for a knowledge-space node (the link a human opens). */\n  async wikiUrl(nodeToken) {\n    const domain = await this.resolveTenantDomain();\n    return domain ? `https://${domain}/wiki/${nodeToken}` : null;\n  }\n\n  /** Resolve a knowledge-space node token to the underlying cloud-document token. */\n  async getWikiNode(nodeToken) {\n    const data = await this._api(\"GET\", `/open-apis/wiki/v2/spaces/get_node?token=${encodeURIComponent(nodeToken)}&obj_type=wiki`);\n    return data?.node ?? null;\n  }\n\n  /**\n   * Create a docx inside a knowledge space.\n   * `obj_token` is the document id every other docx call needs; `node_token` is\n   * the segment that appears in the /wiki/ URL the user sees.\n   */\n  async createWikiDocument(spaceId, title, paragraphs = [], parentNodeToken = \"\") {\n    const body = { obj_type: \"docx\", node_type: \"origin\", title };\n    if (parentNodeToken) body.parent_node_token = parentNodeToken;\n    const data = await this._api(\"POST\", `/open-apis/wiki/v2/spaces/${encodeURIComponent(spaceId)}/nodes`, body);\n    const node = data?.node ?? {};\n    const documentId = assertString(node.obj_token, \"obj_token\");\n    if (paragraphs.length > 0) {\n      await this.appendBlocks(documentId, paragraphs.map((p) => ({ kind: \"text\", text: p })));\n    }\n    return {\n      document_id: documentId,\n      node_token: node.node_token,\n      space_id: spaceId,\n      url: await this.wikiUrl(node.node_token),\n    };\n  }\n\n  // ---------- IM ----------\n  async listChats() {\n    const items = [];\n    let pageToken;\n    do {\n      const path = \"/open-apis/im/v1/chats?page_size=100\" + (pageToken ? `&page_token=${pageToken}` : \"\");\n      const data = await this._api(\"GET\", path);\n      items.push(...(data.items || []));\n      pageToken = data.has_more ? data.page_token : null;\n    } while (pageToken);\n    return items.map((c) => ({ chat_id: c.chat_id, name: c.name }));\n  }\n\n  async listChatMembers(chatId, limit = 100) {\n    const members = [];\n    let pageToken;\n    do {\n      const path = `/open-apis/im/v1/chats/${encodeURIComponent(chatId)}/members?page_size=100`\n        + (pageToken ? `&page_token=${pageToken}` : \"\");\n      const data = await this._api(\"GET\", path);\n      members.push(...(data.items || []));\n      pageToken = data.has_more ? data.page_token : null;\n    } while (pageToken && members.length < limit);\n    return members.slice(0, limit).map((m) => ({\n      member_id: m.member_id,\n      member_id_type: m.member_id_type,\n      name: m.name,\n    }));\n  }\n\n  async sendText(chatId, text) {\n    const body = {\n      receive_id: chatId,\n      msg_type: \"text\",\n      content: JSON.stringify({ text }),\n    };\n    const data = await this._api(\"POST\", \"/open-apis/im/v1/messages?receive_id_type=chat_id\", body);\n    return { message_id: data.message_id, create_time: data.create_time };\n  }\n\n  async sendPost(chatId, title, lines) {\n    const content = {\n      zh_cn: {\n        title: title || \"\",\n        content: (lines || []).map((line) => [{ tag: \"text\", text: String(line) }]),\n      },\n    };\n    const body = { receive_id: chatId, msg_type: \"post\", content: JSON.stringify(content) };\n    const data = await this._api(\"POST\", \"/open-apis/im/v1/messages?receive_id_type=chat_id\", body);\n    return { message_id: data.message_id, create_time: data.create_time };\n  }\n\n  async recallMessage(messageId) {\n    await this._api(\"DELETE\", `/open-apis/im/v1/messages/${encodeURIComponent(messageId)}`);\n    return { message_id: messageId, recalled: true };\n  }\n\n  async readChatHistory(chatId, limit = 30) {\n    const size = Math.min(Math.max(Number(limit) || 30, 1), 100);\n    const path = `/open-apis/im/v1/messages?container_id_type=chat&container_id=${encodeURIComponent(chatId)}&page_size=${size}&sort_type=ByCreateTimeAsc`;\n    const data = await this._api(\"GET\", path);\n    const out = [];\n    for (const m of data.items || []) {\n      const sender = m.sender || {};\n      let text = \"\";\n      try {\n        const obj = JSON.parse((m.body || {}).content || \"{}\");\n        if (m.msg_type === \"text\") text = obj.text || \"\";\n        else if (m.msg_type === \"post\") text = postToPlainText(obj);\n        else text = typeof obj === \"string\" ? obj : JSON.stringify(obj);\n      } catch { /* keep empty */ }\n      out.push({\n        message_id: m.message_id,\n        msg_type: m.msg_type,\n        create_time: m.create_time,\n        sender_type: sender.sender_type,\n        sender_id: sender.id,\n        text,\n      });\n    }\n    return out;\n  }\n\n  // ---------- docx ----------\n  async createDocument(title, paragraphs = []) {\n    const data = await this._api(\"POST\", \"/open-apis/docx/v1/documents\", { title });\n    const doc = data.document || data;\n    const documentId = assertString(doc.document_id, \"document_id\");\n    if (paragraphs.length > 0) {\n      await this.appendBlocks(documentId, paragraphs.map((p) => ({ kind: \"text\", text: p })));\n    }\n    return {\n      document_id: documentId,\n      url: await this.documentUrl(documentId),\n      revision_id: doc.revision_id,\n    };\n  }\n\n  async readDocument(documentId) {\n    const data = await this._api(\"GET\", `/open-apis/docx/v1/documents/${documentId}/raw_content`);\n    return { document_id: documentId, content: data.content || \"\" };\n  }\n\n  async readDocumentBlocks(documentId) {\n    const items = [];\n    let pageToken;\n    do {\n      const path = `/open-apis/docx/v1/documents/${documentId}/blocks?page_size=500`\n        + (pageToken ? `&page_token=${pageToken}` : \"\");\n      const data = await this._api(\"GET\", path);\n      items.push(...(data.items || []));\n      pageToken = data.has_more ? data.page_token : null;\n    } while (pageToken);\n    return items.map((b) => ({\n      block_id: b.block_id,\n      parent_id: b.parent_id,\n      block_type: b.block_type,\n      text: blockPlainText(b),\n      image_token: b.image?.token,\n      table_size: b.table?.property\n        ? { rows: b.table.property.row_size, columns: b.table.property.column_size }\n        : undefined,\n    }));\n  }\n\n  async appendBlocks(documentId, blocks) {\n    const children = [];\n    for (const b of blocks) {\n      const kind = b.kind || \"text\";\n      children.push(blockOf(kind, b.text));\n    }\n    const path = `/open-apis/docx/v1/documents/${documentId}/blocks/${documentId}/children`;\n    const data = await this._api(\"POST\", path, { children });\n    return { added: (data.children || []).length };\n  }\n\n  async updateBlockText(documentId, blockId, text, kind = \"text\") {\n    const path = `/open-apis/docx/v1/documents/${documentId}/blocks/${blockId}?document_revision_id=-1`;\n    const key = kind === \"heading1\" ? \"update_heading1_elements\" : \"update_text_elements\";\n    await this._api(\"PATCH\", path, { [key]: { elements: [{ text_run: { content: text } }] } });\n    return { block_id: blockId, updated: true };\n  }\n\n  async deleteBlock(documentId, blockId) {\n    const info = await this._api(\"GET\", `/open-apis/docx/v1/documents/${documentId}/blocks/${blockId}`);\n    const parentId = info?.block?.parent_id || documentId;\n    const children = await this._api(\n      \"GET\",\n      `/open-apis/docx/v1/documents/${documentId}/blocks/${parentId}/children?page_size=500`,\n    );\n    const items = children.items || [];\n    const index = items.findIndex((b) => b.block_id === blockId);\n    if (index < 0) throw new Error(`block ${blockId} not found under parent ${parentId}`);\n    await this._api(\n      \"DELETE\",\n      `/open-apis/docx/v1/documents/${documentId}/blocks/${parentId}/children/batch_delete`,\n      { start_index: index, end_index: index + 1 },\n    );\n    return { block_id: blockId, deleted: true };\n  }\n\n  async insertTable(documentId, rows, columns) {\n    const body = {\n      children: [{\n        block_type: 31,\n        table: { property: { row_size: Number(rows), column_size: Number(columns) } },\n      }],\n    };\n    const path = `/open-apis/docx/v1/documents/${documentId}/blocks/${documentId}/children?document_revision_id=-1`;\n    const data = await this._api(\"POST\", path, body);\n    const table = (data.children || []).find((b) => b.block_type === 31);\n    return { table_block_id: table?.block_id, rows: Number(rows), columns: Number(columns) };\n  }\n\n  /**\n   * Insert an image buffer into a document.\n   * Feishu requires three steps: create an empty image block, upload the media with\n   * that block as parent_node, then patch the block with the returned file token.\n   */\n  async insertImage(documentId, buffer, filename = \"image.png\") {\n    const created = await this._api(\n      \"POST\",\n      `/open-apis/docx/v1/documents/${documentId}/blocks/${documentId}/children?document_revision_id=-1`,\n      { children: [{ block_type: 27, image: {} }], index: -1 },\n    );\n    const blockId = (created.children || []).find((b) => b.block_type === 27)?.block_id;\n    if (!blockId) throw new Error(\"failed to create an empty image block\");\n\n    const form = new FormData();\n    form.append(\"file_name\", filename);\n    form.append(\"parent_type\", \"docx_image\");\n    form.append(\"parent_node\", blockId);\n    form.append(\"size\", String(buffer.length));\n    form.append(\"extra\", JSON.stringify({ drive_route_token: documentId }));\n    form.append(\"file\", new Blob([buffer]), filename);\n    const uploaded = await this._upload(\"/open-apis/drive/v1/medias/upload_all\", form);\n    const token = uploaded.file_token;\n    if (!token) throw new Error(\"image upload returned no file_token\");\n\n    await this._api(\n      \"PATCH\",\n      `/open-apis/docx/v1/documents/${documentId}/blocks/${blockId}?document_revision_id=-1`,\n      { replace_image: { token } },\n    );\n    return { block_id: blockId, file_token: token, bytes: buffer.length };\n  }\n\n  // ---------- bitable ----------\n  async createBitable(name) {\n    const data = await this._api(\"POST\", \"/open-apis/bitable/v1/apps\", { name });\n    const app = data.app || data;\n    const appToken = assertString(app.app_token, \"app_token\");\n    return { app_token: appToken, name: app.name, url: await this.bitableUrl(appToken) };\n  }\n\n  async listBitableTables(appToken) {\n    const data = await this._api(\"GET\", `/open-apis/bitable/v1/apps/${appToken}/tables?page_size=100`);\n    return (data.items || []).map((t) => ({ table_id: t.table_id, name: t.name }));\n  }\n\n  async listBitableFields(appToken, tableId) {\n    const data = await this._api(\n      \"GET\",\n      `/open-apis/bitable/v1/apps/${appToken}/tables/${tableId}/fields?page_size=100`,\n    );\n    return (data.items || []).map((f) => ({ field_id: f.field_id, field_name: f.field_name, type: f.type }));\n  }\n\n  async createBitableRecord(appToken, tableId, fields) {\n    const data = await this._api(\n      \"POST\",\n      `/open-apis/bitable/v1/apps/${appToken}/tables/${tableId}/records`,\n      { fields },\n    );\n    const record = data.record || data;\n    return { record_id: record.record_id, fields: record.fields };\n  }\n\n  async listBitableRecords(appToken, tableId, limit = 20) {\n    const size = Math.min(Math.max(Number(limit) || 20, 1), 100);\n    const data = await this._api(\n      \"GET\",\n      `/open-apis/bitable/v1/apps/${appToken}/tables/${tableId}/records?page_size=${size}`,\n    );\n    return (data.items || []).map((r) => ({ record_id: r.record_id, fields: r.fields }));\n  }\n\n  // ---------- sheets (classic v2 range API) ----------\n  async readSheetRange(spreadsheetToken, range) {\n    const data = await this._api(\n      \"GET\",\n      `/open-apis/sheets/v2/spreadsheets/${spreadsheetToken}/values/${encodeURIComponent(range)}`,\n    );\n    return { range: data.valueRange?.range ?? range, values: data.valueRange?.values ?? [] };\n  }\n\n  async writeSheetRange(spreadsheetToken, range, values) {\n    const data = await this._api(\n      \"PUT\",\n      `/open-apis/sheets/v2/spreadsheets/${spreadsheetToken}/values`,\n      { valueRange: { range, values } },\n    );\n    return { updated: data.updatedCells ?? null, range: data.updatedRange ?? range };\n  }\n\n  // ---------- drive permission ----------\n  /**\n   * Set link sharing for a document or bitable owned by the app, so that people\n   * with the link (in the tenant, or anyone) can open it.\n   */\n  async setLinkSharing(token, type, linkShareEntity = \"tenant_readable\", linkSharePerm = \"view\") {\n    const body = { link_share_entity: linkShareEntity, link_share_perm: linkSharePerm };\n    const path = `/open-apis/drive/v1/permissions/${token}/public?type=${encodeURIComponent(type)}`;\n    const data = await this._api(\"PATCH\", path, body);\n    return {\n      ok: true,\n      token,\n      type,\n      link_share_entity: data?.permission_public?.link_share_entity ?? linkShareEntity,\n    };\n  }\n\n  async grantAccess(token, type, openId, perm = \"full_access\") {\n    const body = { member_type: \"openid\", member_id: openId, perm };\n    const path = `/open-apis/drive/v1/permissions/${token}/members?type=${encodeURIComponent(type)}`;\n    await this._api(\"POST\", path, body);\n    return { ok: true, token, type, open_id: openId, perm };\n  }\n}\n\n// ---------- helpers ----------\nfunction blockOf(kind, text) {\n  const elements = [{ text_run: { content: text ?? \"\", text_element_style: {} } }];\n  if (kind === \"heading1\") return { block_type: 3, heading1: { elements } };\n  if (kind === \"heading2\") return { block_type: 4, heading2: { elements } };\n  if (kind === \"bullet\") return { block_type: 12, bullet: { elements } };\n  if (kind === \"quote\") return { block_type: 15, quote: { elements } };\n  return { block_type: 2, text: { elements } };\n}\n\nfunction blockPlainText(block) {\n  const containers = [block.text, block.heading1, block.heading2, block.bullet, block.quote, block.code];\n  for (const c of containers) {\n    if (c?.elements) {\n      return c.elements\n        .map((e) => e.text_run?.content ?? \"\")\n        .join(\"\");\n    }\n  }\n  return \"\";\n}\n\nfunction postToPlainText(post) {\n  const lines = post?.zh_cn?.content || post?.en_us?.content || [];\n  const out = [];\n  for (const row of lines) {\n    out.push((row || []).map((e) => e.text ?? e.href ?? \"\").join(\"\"));\n  }\n  const title = post?.zh_cn?.title || post?.en_us?.title;\n  return (title ? title + \"\\n\" : \"\") + out.join(\"\\n\");\n}\n"
